func PathEscape(pth string) string {
	// Treat the input as a path, not a URL. This makes sure that
	// characters such as '#' and '?' are escaped instead of being
	// interpreted as a fragment/query delimiter.
	u := url.URL{Path: pth}
	return u.EscapedPath()
}

